package com.muneebwanee.bookwiz;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.Build;
import org.json.*;
public final class WritingReminders extends android.content.BroadcastReceiver {
 private static final String CHANNEL="bookwiz-writing";
 static boolean allowed(Context c){NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)return false;NotificationChannel channel=n.getNotificationChannel(CHANNEL);return n.areNotificationsEnabled()&&(channel==null||channel.getImportance()!=NotificationManager.IMPORTANCE_NONE);}
 static void apply(Context c,String json){cancel(c);try{JSONObject data=new JSONObject(json);c.getSharedPreferences("bookwiz-reminders",0).edit().putString("plan",json).apply();if(data.optBoolean("enabled")&&allowed(c))scheduleNext(c);}catch(Exception ignored){}}
 static void cancel(Context c){AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);PendingIntent p=PendingIntent.getBroadcast(c,910,new Intent(c,WritingReminders.class).setAction("com.muneebwanee.bookwiz.REMINDER"),PendingIntent.FLAG_NO_CREATE|PendingIntent.FLAG_IMMUTABLE);if(p!=null){a.cancel(p);p.cancel();}((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).cancel(910);}
 private static JSONObject next(Context c){try{JSONObject p=new JSONObject(c.getSharedPreferences("bookwiz-reminders",0).getString("plan","{}"));if(!p.optBoolean("enabled"))return null;JSONArray list=p.optJSONArray("plans");if(list==null)return null;JSONObject best=null;for(int i=0;i<Math.min(14,list.length());i++){JSONObject item=list.getJSONObject(i);long at=item.optLong("at");if(at>System.currentTimeMillis()&&(best==null||at<best.optLong("at")))best=item;}return best;}catch(Exception ignored){return null;}}
 static void scheduleNext(Context c){JSONObject n=next(c);if(n==null||!allowed(c))return;Intent i=new Intent(c,WritingReminders.class).setAction("com.muneebwanee.bookwiz.REMINDER").putExtra("body",n.optString("body")).putExtra("at",n.optLong("at"));PendingIntent p=PendingIntent.getBroadcast(c,910,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,n.optLong("at"),p);}
 private static boolean outsideQuietHours(Context c){try{JSONObject p=new JSONObject(c.getSharedPreferences("bookwiz-reminders",0).getString("plan","{}"));String[] a=p.optString("quietStart","22:00").split(":"),b=p.optString("quietEnd","08:00").split(":");int start=Integer.parseInt(a[0])*60+Integer.parseInt(a[1]),end=Integer.parseInt(b[0])*60+Integer.parseInt(b[1]);java.util.Calendar now=java.util.Calendar.getInstance();int time=now.get(java.util.Calendar.HOUR_OF_DAY)*60+now.get(java.util.Calendar.MINUTE);String day=now.get(java.util.Calendar.YEAR)+"-"+now.get(java.util.Calendar.DAY_OF_YEAR);android.content.SharedPreferences prefs=c.getSharedPreferences("bookwiz-reminders",0);if(day.equals(prefs.getString("lastDay",""))||start!=end&&(start<end?time>=start&&time<end:time>=start||time<end))return false;prefs.edit().putString("lastDay",day).apply();return true;}catch(Exception e){return false;}}
 @Override public void onReceive(Context c,Intent i){if(!"com.muneebwanee.bookwiz.REMINDER".equals(i.getAction())){cancel(c);if(Intent.ACTION_TIMEZONE_CHANGED.equals(i.getAction()))c.getSharedPreferences("bookwiz-reminders",0).edit().remove("plan").apply();else scheduleNext(c);return;}if(!MainActivity.foreground&&allowed(c)&&System.currentTimeMillis()-i.getLongExtra("at",0)<3600000&&outsideQuietHours(c)){NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);n.createNotificationChannel(new NotificationChannel(CHANNEL,"Writing reminders",NotificationManager.IMPORTANCE_DEFAULT));Intent open=new Intent(c,MainActivity.class).setAction("com.muneebwanee.bookwiz.OPEN_REMINDER").putExtra("bookwiz-widget","resume").setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent tap=PendingIntent.getActivity(c,910,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);n.notify(910,new Notification.Builder(c,CHANNEL).setSmallIcon(R.drawable.ic_reminder).setContentTitle("A little room for your words").setContentText(i.getStringExtra("body")).setStyle(new Notification.BigTextStyle().bigText(i.getStringExtra("body"))).setContentIntent(tap).setAutoCancel(true).setVisibility(Notification.VISIBILITY_PRIVATE).setOnlyAlertOnce(true).build());}scheduleNext(c);}
}
